def get_user(db, name):
    query = "SELECT * FROM users WHERE name = '" + name + "'"
    cur = db.execute(query)
    return cur.fetchone()

def get_user(db, name):
    query = "SELECT * FROM users WHERE name = ?"
    cur = db.execute(query, (name,))
    return cur.fetchone()

def moving_sum(xs, k):
    out = []
    for i in range(len(xs) - k + 2):
        out.append(sum(xs[i:i + k]))
    return out

def moving_sum(xs, k):
    out = []
    for i in range(len(xs) - k + 1):
        out.append(sum(xs[i:i + k]))
    return out

def list_events(db, user_id):
    rows = db.execute("SELECT * FROM events WHERE user_id = ?", (user_id,))
    return [dict(r) for r in rows.fetchall()]

def list_events(db, user_id, limit=100):
    limit = min(limit, 500)
    rows = db.execute(
        "SELECT * FROM events WHERE user_id = ? ORDER BY id DESC LIMIT ?", (user_id, limit)
    )
    return [dict(r) for r in rows.fetchall()]
